package dev.lab.victim

import java.net.InetAddress
import java.util.concurrent.TimeUnit
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.OkHttpClient
import okhttp3.Request

/**
 * Generates the lab traffic for the verification scenarios.
 *
 * Every request carries an `X-VPNLab-Scenario` marker header so the traffic
 * generated by this app can be attributed in pcaps and in mitmproxy output,
 * without relying on the body markers alone (VPNLAB-BASELINE, ...).
 *
 * Base URLs used with the lab server (server/labserver.py):
 *   http://http.lab.test:8080   -> /baseline, /ads, /redirect
 *   https://secure.lab.test:8443 -> /secure
 *
 * Certificate pinning note: [pinSha256] is the OkHttp/standard-style pin — the
 * SHA-256 digest of the certificate's SubjectPublicKeyInfo (SPKI),
 * hex-encoded, base64 form also accepted. It is the hash of the *key*, not of
 * the whole certificate, so it survives the mitmproxy CA's re-issuance of the
 * leaf only when the key is reused (the lab regenerates fresh keys, hence the
 * pinned connection is expected to FAIL under interception — Task 11).
 */
class TrafficClient(
    connectTimeoutSeconds: Long = 5,
    readTimeoutSeconds: Long = 10,
) {
    /** Marker header carrying the scenario name of the current request. */
    companion object {
        const val MARKER_HEADER = "X-VPNLab-Scenario"
        const val CLIENT_HEADER = "X-VPNLab-Client"
        const val CLIENT_VALUE = "victim-lab"
    }

    private val client: OkHttpClient = OkHttpClient.Builder()
        .connectTimeout(connectTimeoutSeconds, TimeUnit.SECONDS)
        .readTimeout(readTimeoutSeconds, TimeUnit.SECONDS)
        .followRedirects(true)
        .build()

    private fun request(url: String, scenario: String): Request =
        Request.Builder()
            .url(url)
            .header(CLIENT_HEADER, CLIENT_VALUE)
            .header(MARKER_HEADER, scenario)
            .build()

    /**
     * Fetches `<baseUrl>/baseline` (cleartext HTTP marker page VPNLAB-BASELINE).
     */
    suspend fun fetchBaseline(baseUrl: String): String =
        fetch("${baseUrl.trimEnd('/')}/baseline", "baseline")

    /**
     * Fetches `<baseUrl>/ads` (expected to be blocked/rewritten by the
     * mitmproxy ad-block scenario, VPNLAB-REWRITTEN).
     */
    suspend fun fetchAds(baseUrl: String): String =
        fetch("${baseUrl.trimEnd('/')}/ads", "ads")

    /**
     * Fetches `<baseUrl>/redirect`, which the lab server answers with a 302 to
     * `/landing`. With redirects enabled the final body is the landing page, so
     * on-device this proves the HTTP redirect was honored (or rewritten to
     * VPNLAB-PARTNER by the interception scenario).
     */
    suspend fun followRedirect(baseUrl: String): String =
        fetch("${baseUrl.trimEnd('/')}/redirect", "redirect")

    /**
     * Fetches `https://secure.lab.test:8443/secure` — the HTTPS marker page
     * (VPNLAB-SECURE) whose certificate is signed by the lab mitmproxy CA
     * (trusted through the user-CA domain rule for secure.lab.test).
     * baseUrl may point at any host; the call simply GETs `/secure` on it.
     */
    suspend fun fetchSecure(baseUrl: String): String =
        fetch("${baseUrl.trimEnd('/')}/secure", "secure")

    /**
     * Resolves [host] through the system resolver (dnsmasq on the lab AP).
     * Callers use this to check whether the VPN tunnel or Private DNS leaked
     * the query to a different resolver than 10.42.0.2.
     */
    suspend fun resolveHost(host: String): List<InetAddress> =
        withContext(Dispatchers.IO) {
            InetAddress.getAllByName(host).toList()
        }

    /**
     * Fetches `/secure` while pinning the server certificate to [pinSha256]
     * (SHA-256 of the leaf's SPKI, see class doc). A MITM with a different key
     * makes this fail with an SSLPeerUnverifiedException — used in Task 11 to
     * show that pinning stops the interception scenario.
     */
    suspend fun fetchPinnedSecure(baseUrl: String, pinSha256: String): String {
        val pin = normalizePin(pinSha256)
        val pinned = client.newBuilder()
            .certificatePinner(
                CertificatePinnerBytes.pinFor(hostOf(baseUrl), pin)
            )
            .build()
        return withContext(Dispatchers.IO) {
            pinned.newCall(request("${baseUrl.trimEnd('/')}/secure", "pinned-secure"))
                .execute().use { response ->
                    check(response.isSuccessful) {
                        "pinned request failed: HTTP ${response.code}"
                    }
                    response.body?.string().orEmpty()
                }
        }
    }

    private suspend fun fetch(url: String, scenario: String): String {
        return withContext(Dispatchers.IO) {
            client.newCall(request(url, scenario)).execute().use { response ->
                check(response.isSuccessful) { "$scenario request failed: HTTP ${response.code}" }
                response.body?.string().orEmpty()
            }
        }
    }

    private fun hostOf(url: String): String {
        val trimmed = url.trim().removePrefix("https://").removePrefix("http://")
        return trimmed.substringBefore('/').substringBefore(':')
    }

    internal fun normalizePin(raw: String): String {
        val v = raw.trim().removePrefix("sha256/").removePrefix("pin-sha256=\"").trimEnd('"')
        require(v.isNotEmpty()) { "empty pin" }
        // Accept either a base64 pin (OkHttp style) or a hex digest; validate
        // shape so the error surfaces here rather than deep inside OkHttp.
        val isHex = v.length == 64 && v.all { it in "0123456789abcdefABCDEF" }
        val isB64 = v.length == 44 && v.endsWith("=")
        require(isHex || isB64) {
            "pinSha256 must be 32 bytes as hex (64 chars) or base64 (44 chars ending in '=')"
        }
        return if (isHex) CertificatePinnerBytes.hexToBase64(v) else v
    }
}

/** Internal helper object; kept out of TrafficClient so OkHttp types stay isolated. */
internal object CertificatePinnerBytes {
    fun pinFor(host: String, base64SpkiSha256: String): okhttp3.CertificatePinner =
        okhttp3.CertificatePinner.Builder()
            .add(host, "sha256/$base64SpkiSha256")
            .build()

    fun hexToBase64(hex: String): String {
        val bytes = ByteArray(hex.length / 2)
        for (i in bytes.indices) {
            bytes[i] = ((Character.digit(hex[2 * i], 16) shl 4)
                    + Character.digit(hex[2 * i + 1], 16)).toByte()
        }
        return java.util.Base64.getEncoder().encodeToString(bytes)
    }
}
